const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';

function genHeaders() {
  const timestamp = Date.now();
  const uuid = crypto.randomUUID();
  const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
  const key = Buffer.from(secretKey.slice(0, 16), 'utf-8');
  const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
  const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
  let encrypted = cipher.update(comboxKey, 'utf-8', 'base64');
  encrypted += cipher.final('base64');
  return { 'Content-Type': 'application/json', 'ACCEPT': 'application/json', 'accessKey': accessKey, 'signature': encrypted };
}

const input = $input.first().json;
const reviewId = input.review_id;
if (!reviewId) throw new Error('review_id is required');
const page = input.page || 1;
const pageSize = input.page_size || 20;

const detailRes = await fetch(`${baseUrl}/track/test/case/review/get/${reviewId}`, { headers: genHeaders() });
const detail = await detailRes.json();

const reviewerRes = await fetch(`${baseUrl}/track/test/case/review/reviewer`, { method: 'POST', headers: genHeaders(), body: JSON.stringify({ id: reviewId }) });
const reviewerData = await reviewerRes.json();

const casesRes = await fetch(`${baseUrl}/track/test/review/case/list/${page}/${pageSize}`, { method: 'POST', headers: genHeaders(), body: JSON.stringify({ reviewId }) });
const casesData = await casesRes.json();

const d = detail.data || {};
const result = {
  id: d.id, name: d.name, status: d.status, creator: d.creator, description: d.description || '', pass_rule: d.reviewPassRule,
  end_time: d.endTime ? new Date(d.endTime).toISOString() : null, create_time: d.createTime ? new Date(d.createTime).toISOString() : null,
  reviewers: (reviewerData.data || []).map(r => ({ id: r.id, name: r.name, email: r.email })),
  cases: { items: ((casesData.data && casesData.data.listObject) || []).map(c => ({ id: c.id, name: c.name, priority: c.priority, review_status: c.reviewStatus, maintainer: c.maintainer })), total: (casesData.data && casesData.data.itemCount) || 0 }
};

return [{ json: result }];
